+const { useState } = React;
+
+function RadioOption({ name, value, label, checked, onChange }) {
+  return (
+    <label className={"radio-option" + (checked ? " checked" : "")}>
+      <input
+        type="radio"
+        name={name}
+        value={value}
+        checked={checked}
+        onChange={onChange}
+      />
+      <span className="radio-label">{label}</span>
+    </label>
+  );
+}
+
+function NotificationForm() {
+  const options = [
+    { value: "email", label: "Email" },
+    { value: "sms", label: "SMS" },
+    { value: "push", label: "Push Notifications" },
+  ];
+
+  const [selected, setSelected] = useState("");
+  const [submitted, setSubmitted] = useState(null);
+
+  const handleSubmit = (e) => {
+    e.preventDefault();
+    if (!selected) return;
+    const label = options.find((o) => o.value === selected).label;
+    setSubmitted(label);
+  };
+
+  return (
+    <div className="card">
+      <div className="card-header">
+        <h1 className="card-title">Notification Preferences</h1>
+        <p className="card-subtitle">Tell us how to reach you.</p>
+      </div>
+      <form onSubmit={handleSubmit} noValidate>
+        <div className="form-field">
+          <fieldset>
+            <legend>How do you prefer to receive notifications?</legend>
+            {options.map((opt) => (
+              <RadioOption
+                key={opt.value}
+                name="notification"
+                value={opt.value}
+                label={opt.label}
+                checked={selected === opt.value}
+                onChange={() => {
+                  setSelected(opt.value);
+                  setSubmitted(null);
+                }}
+              />
+            ))}
+          </fieldset>
+        </div>
+        <button type="submit" className="submit-btn" disabled={!selected}>
+          Submit
+        </button>
+        {submitted && (
+          <div className="confirmation">
+            Preference saved: {submitted}
+          </div>
+        )}
+      </form>
+    </div>
+  );
+}
+
+const root = ReactDOM.createRoot(document.getElementById("root"));
+root.render(<NotificationForm />);
+
